  amount(value,ctx){if(value.kind==='mutation-count-v69')return Math.max(0,Number(ctx.sourceMeta?.c1920Mutations??ctx.src.meta?.c1920Mutations)||0);if(value.kind==='opponents-artifact-plus-one-v69')return 1+ctx.g.alivePlayers().filter(player=>player!==ctx.you&&ctx.g.bf().some(c=>c.ctrl===player&&c.is('Artifact'))).length;if(value.kind==='damage-event-v69')return Math.max(0,Number(ctx.data?.n)||0);if(value.kind==='life-event-v69')return Math.max(0,Number(ctx.data?.n)||0);if(value.kind==='opponents-small-hand-v69')return ctx.g.players.filter(x=>x!==ctx.you&&x.hand.length<=1).length;if(value.kind==='three-minus-event-hand-v69'){const player=H.genericEffectSubjects(ctx,'event-player')[0];return Math.max(0,3-(player?.hand.length??3));}if(value.kind==='smashing-x-v69'){const x=Number(ctx.x??ctx.so?.x??0);return x*(x>=6?2:1);}if(value.kind==='other-attacking-v69')return Math.max(0,ctx.g.bf().filter(c=>c.is('Creature')&&c.attacking).length-1);},
