  condition(g,s,node,p,context){if(node.kind==='combat-six-v69'){const hits=g.players.flatMap(player=>player.turnState.combatDamageHits||[]);return g.players.some(player=>hits.filter(hit=>hit.player===player).reduce((n,hit)=>n+hit.n,0)>=6);}if(node.kind==='opponent-noncombat-damage-v69')return g.players.some(x=>x!==p&&x.turnState.noncombatDamageV69===g.turnNo);if(node.kind==='event-player-hand-small-v69')return context?.eventPlayer?.hand.length<=1;if(node.kind==='first-legendary-creature-v69')return !p.turnState.spellsCastList.some(row=>row.isCreature&&row.supertypes?.includes('Legendary'));if(node.kind==='opponent-creature-died-v69')return g.diedThisTurn.some(row=>row.types.includes('Creature')&&row.ctrl!==p);},
  count(g,s,p,node){if(node.kind==='spirit-enchant-v69')return g.bf().filter(c=>c.ctrl===p&&(c.hasSub('Spirit')||c.is('Enchantment'))).length;if(node.kind==='unlocked-room-names-v69')return new Set(g.bf().filter(c=>c.ctrl===p&&c.def.bdfRoom).flatMap(c=>c.def.bdfRoom.filter(door=>M.BDF.bdfUnlocked(c,door.key)).map(door=>door.name))).size;if(node.kind==='opponents-artifact-plus-one-v69')return 1+g.alivePlayers().filter(player=>player!==p&&g.bf().some(c=>c.ctrl===player&&c.is('Artifact'))).length;if(node.kind==='source-auras-v69')return g.bf().filter(c=>c.attachedTo===s.iid&&c.hasSub('Aura')&&!c.phasedOut).length;if(node.kind==='opponents-small-hand-v69')return g.players.filter(x=>x!==p&&x.hand.length<=1).length;if(node.kind==='opponents-drawn-v69')return g.players.filter(x=>x!==p).reduce((n,x)=>n+(x.turnState.drewThisTurn||0),0);if(node.kind==='alrund-hand-foretell-v69')return p.hand.length+p.exile.filter(c=>c.owner===p&&c.meta.foretold&&c.meta.foretoldZoneVersion===c.zoneVersion).length;if(node.kind==='other-attacking-v69')return Math.max(0,g.bf().filter(c=>c.is('Creature')&&c.attacking).length-1);if(node.kind==='opponents-life-lost-v69')return g.players.filter(x=>x!==p).reduce((n,x)=>n+(x.turnState.lifeLost||0),0);if(node.kind!=='permanent-types-v69')return undefined;return new Set(p.graveyard.flatMap(c=>c.def.types.filter(t=>['Artifact','Battle','Creature','Enchantment','Land','Planeswalker'].includes(t)))).size;},
